// Dropdowns copied from the LIVE app (yopmail staging, 18 Nov 2026) — Step 7 of the component library.
// Every class string, icon and CSS rule comes from _kit/src/data/dropdownLive.js + _kit/src/dropdowns-live.css, generated by
// _graph/jobs/dropdowns-2026-11-18/extract.py from live state captures. Nothing here is typed from memory: this file only decides
// WHICH captured state to show (closed / open / hover / value / no match / disabled) and puts the option text in.
//
// <LiveSelect variant=…>   react-select, the same DOM the app renders. Variants (where each was captured live):
//   form      field on add/edit forms             CRM › Companies › Add › Industry      (closed 1ltf6eg, focused/open tmene0)
//   disabled  a form field that waits for another  CRM › Companies › Add › State         (gjy5sx)
//   status    form field with coloured dots        People › Employee › Add › Status      (Intern / Probation / Confirmed)
//   pagesize  records per page under every list    CRM › Companies (opens upwards)        (10 / 25 / 50 / 100)
//   filter    Σ search-mode picker in list search  CRM › Companies                       (Look-up Filter / Quick Search)
//   pm        the same Σ picker in Project Mgmt    PM › Projects
//   table     borderless select inside a table row Administration › Email Status
//   multi     chips multi-select (isMulti)         CRM › Config › Operational Config › Edit
// <LivePrimeMulti>          PrimeReact multi-select with checkboxes + search   CRM › Companies › Business Unit filter
// Full live pages these were copied from (graph links them):
//   modules/crm-invoice/dom/yop_dropdowns_form_2026-11-18.html     modules/crm-invoice/dom/yop_dropdowns_filter_2026-11-18.html
//   modules/crm-invoice/dom/yop_dropdowns_multi_2026-11-18.html    modules/people/dom/yop_dropdowns_status_2026-11-18.html
//   modules/admin/dom/yop_dropdowns_table_2026-11-18.html          modules/project-mgmt/dom/yop_dropdowns_pm_2026-11-18.html
// Check page: /check/dropdowns (live screenshot beside the kit for 28 states).
import { useState, useRef, useEffect, useMemo } from 'react'
import { DD } from '../data/dropdownLive.js'
import '../dropdowns-live.css'

const css2obj = (s = '') => Object.fromEntries(s.split(';').map((d) => d.split(':')).filter((p) => p.length > 1 && p[0].trim())
  .map(([k, ...v]) => [k.trim().replace(/-([a-z])/g, (_, c) => c.toUpperCase()), v.join(':').trim()]))
const isFocusedCls = (c) => /--is-focused/.test(c)
const isSelectedCls = (c) => /--is-selected/.test(c)

// Option classes per index, read from every captured open list: normal / focused / selected.
function optionTable(v) {
  const lists = Object.entries(v.opts || {}).filter(([, o]) => o.cls && o.cls.length > 1)
  const all = lists.flatMap(([, o]) => o.cls)
  const count = {}; all.forEach((c) => { count[c] = (count[c] || 0) + 1 })
  const plain = Object.keys(count).filter((c) => !isFocusedCls(c) && !isSelectedCls(c)).sort((a, b) => count[b] - count[a])
  const normal = plain[0]
  const prefixless = !/react-select__option/.test(all[0] || '')
  // prefix-less (multi): the focused option is the one in the hover list (index 1) whose class differs from the normal one
  const focused = all.find((c) => isFocusedCls(c) && !isSelectedCls(c)) || (prefixless && v.opts.hover ? v.opts.hover.cls.find((c) => c !== normal) : null) || normal
  const selected = all.find((c) => isSelectedCls(c)) || null
  const focusedSelected = all.find((c) => isSelectedCls(c) && isFocusedCls(c)) || selected
  // per-index colours (Status dots): the same index keeps its own hash in every list
  const perIdx = {}
  lists.forEach(([, o]) => o.cls.forEach((c, i) => { const slot = (perIdx[i] = perIdx[i] || {}); if (isFocusedCls(c)) slot.focused = c; else slot.normal = slot.normal || c }))
  const distinct = new Set(Object.values(perIdx).map((s) => s.normal)).size === Object.keys(perIdx).length && Object.keys(perIdx).length > 2 && !selected
  return { normal, focused, selected, focusedSelected, perIdx: distinct ? perIdx : null }
}

export function LiveSelect({ variant = 'form', options = [], value = null, onChange, placeholder, disabled = false, searchable,
  forceOpen = false, hoverIndex = null, forceInput = null, width, id = 3, menuInner = null }) {
  const v = DD[disabled ? 'disabled' : variant] || DD.form
  const isMulti = variant === 'multi'
  const canSearch = searchable ?? ['form', 'status', 'table', 'multi'].includes(variant)
  const [open, setOpen] = useState(forceOpen)
  const [input, setInput] = useState(forceInput ?? '')
  const [hover, setHover] = useState(hoverIndex)
  const ref = useRef(null)
  useEffect(() => {
    if (forceOpen) return
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) { setOpen(false); setInput('') } }
    document.addEventListener('mousedown', h, true); return () => document.removeEventListener('mousedown', h, true)
  }, [forceOpen])
  const vals = isMulti ? (value || []) : (value != null && value !== '' ? [value] : [])
  const shown = options.filter((o) => !input || String(o).toLowerCase().includes(input.toLowerCase())).filter((o) => !isMulti || !vals.includes(o))
  const noMatch = open && shown.length === 0
  // which captured state to copy
  const withMenu = (...xs) => xs.find((x) => x && x.menu) || xs.find(Boolean)
  const st = disabled ? (v.st.disabled || v.st.field) : open ? (noMatch && v.st.nomatch ? v.st.nomatch
      : withMenu(vals.length && !isMulti ? v.st.valueopen : null, v.st.open, v.st.hover, v.st.nomatch))
    : vals.length && !v.st.closed?.singleValue && !v.st.closed?.multiValue && v.st.value ? v.st.value : v.st.closed
  const stName = Object.keys(v.st).find((k) => v.st[k] === st)
  const html = v.html[stName] || {}
  const ot = useMemo(() => optionTable(v), [v])
  const pick = (o) => { if (isMulti) onChange?.([...vals, o]); else { onChange?.(o); setOpen(false) } setInput('') }
  const toggle = (e) => { if (disabled || forceOpen) return; if (e.target.closest('[data-clear]')) return; setOpen((x) => !x) }
  const onIndicators = (e) => {   // the clear "x" is the first indicator when there is a value (react-select order: clear, dropdown)
    const ind = e.currentTarget.children; if (vals.length && ind.length > 1 && ind[0].contains(e.target)) { e.stopPropagation(); onChange?.(isMulti ? [] : null) }
  }
  const optCls = (i, o) => {
    const idx = options.indexOf(o)
    if (ot.perIdx && ot.perIdx[idx]) return hover === i ? (ot.perIdx[idx].focused || ot.perIdx[idx].normal) : ot.perIdx[idx].normal
    const sel = vals.includes(o) && !isMulti
    if (sel) return hover === i ? ot.focusedSelected : (ot.selected || ot.normal)
    return hover === i ? ot.focused : ot.normal
  }
  const inputEl = canSearch && st.input != null
    ? <div className={st.inputContainer} data-value={input}>
        <input className={st.input} autoCapitalize="none" autoComplete="off" autoCorrect="off" id={`react-select-${id}-input`} spellCheck="false" tabIndex="0"
          type="text" aria-autocomplete="list" aria-expanded={open} aria-haspopup="true" role="combobox" aria-activedescendant="" value={input}
          disabled={disabled} onChange={(e) => { setInput(e.target.value); setOpen(true) }} style={css2obj(st.inputStyle)} />
      </div>
    : html.dummyInput ? <span style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: html.dummyInput }} /> : null
  return (
    <div ref={ref} className={st.container} style={width ? { width } : v.w ? { width: v.w } : undefined}>
      <span id={`react-select-${id}-live-region`} className={st.a11y} />
      {/* react-select's screen-reader log: filled while the select has focus (open, or just picked), texts in react-select's own words (live) */}
      {st.a11yLog
        ? <span aria-live="polite" aria-atomic="false" aria-relevant="additions text" role="log" className={st.a11y}>
            <span id="aria-selection">{vals.length && !isMulti ? `option ${vals[0]}, selected.` : ''}</span>
            <span id="aria-focused" />
            <span id="aria-results">{open ? (noMatch && input ? `0 results available for search term ${input}.` : `${shown.length} results available.`) : ''}</span>
            <span id="aria-guidance">{v.a11yGuidance || DD.form.a11yGuidance}</span>
          </span>
        : <span aria-live="polite" aria-atomic="false" aria-relevant="additions text" role="log" className={st.a11y} />}
      <div className={st.control} onMouseDown={(e) => { if (e.target.tagName !== 'INPUT') e.preventDefault(); toggle(e) }} aria-disabled={disabled || undefined}>
        <div className={st.valueContainer}>
          {isMulti && vals.map((o) => (
            <div key={o} className={st.multiValue || v.st.closed.multiValue}>
              <div className={st.multiValueLabel || v.st.closed.multiValueLabel}>{o}</div>
              <div role="button" className={st.multiValueRemove || v.st.closed.multiValueRemove} aria-label={`Remove ${o}`}
                onMouseDown={(e) => { e.stopPropagation(); onChange?.(vals.filter((x) => x !== o)) }}
                dangerouslySetInnerHTML={{ __html: html.multiValueRemove || v.html.closed.multiValueRemove }} />
            </div>
          ))}
          {!isMulti && !input && (vals.length
            ? (html.singleValue && !options.length) || (html.singleValue && /icon-/.test(html.singleValue))
              ? <div className={st.singleValue || v.st.value?.singleValue} dangerouslySetInnerHTML={{ __html: html.singleValue }} />
              : <div className={st.singleValue || v.st.value?.singleValue || v.st.closed.singleValue}>{vals[0]}</div>
            : <div className={st.placeholder || v.st.closed.placeholder}>{placeholder ?? 'Select'}</div>)}
          {inputEl}
        </div>
        <div className={st.indicators} onMouseDown={onIndicators} dangerouslySetInnerHTML={{ __html: indicatorsFor(v, stName, vals.length > 0) }} />
      </div>
      {open && st.menu && (
        // live: react-select portals the menu (menu-portal) with a position computed for that page; DIVERGES: here the portal is placed on the box
        <MenuPortal cls={st.menuPortal} up={v.menuUp}>
        <div className={st.menu}>
          <div className={st.menuList}>
            {noMatch
              ? <div className={v.st.nomatch?.notice || st.notice}>{(v.html.nomatch?.notice) || 'No options'}</div>
              : shown.map((o, i) => (
                <div key={o} className={optCls(i, o)} onMouseEnter={() => setHover(i)} onMouseDown={(e) => { e.preventDefault(); pick(o) }}
                  aria-disabled="false" tabIndex="-1">{menuInner ? <span style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: menuInner(o) }} /> : o}</div>
              ))}
          </div>
        </div>
        </MenuPortal>
      )}
    </div>
  )
}
const MenuPortal = ({ cls, up, children }) => cls
  ? <div className={cls} style={{ position: 'absolute', left: 0, width: '100%', top: up ? 0 : '100%', zIndex: 9999 }}>{children}</div>
  : children

// indicators markup, verbatim from the matching state; a closed select WITH a value uses the 'value' capture (it carries the clear x)
function indicatorsFor(v, stName, hasValue) {
  const h = v.html[stName]?.indicators ?? v.html.closed?.indicators ?? ''
  if (!hasValue || /clear/.test(h) || !v.html.value?.indicators) return h
  if (stName === 'closed' && /clear/.test(v.html.value.indicators)) return v.html.value.indicators
  return h
}

// ── PrimeReact multi-select with checkboxes (CRM list "Select Business Unit" filter) ──
export function LivePrimeMulti({ options = [], values = [], onChange, placeholder = 'Select Business Unit', forceOpen = false, hoverIndex = null, width }) {
  const v = DD.prime
  const [open, setOpen] = useState(forceOpen)
  const [hover, setHover] = useState(hoverIndex)
  const [q, setQ] = useState('')
  const ref = useRef(null)
  useEffect(() => {
    if (forceOpen) return
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false) }
    document.addEventListener('mousedown', h, true); return () => document.removeEventListener('mousedown', h, true)
  }, [forceOpen])
  useEffect(() => { if (open) ref.current?.querySelector('.p-multiselect-panel input')?.focus() }, [open])   // live: the search box gets focus on open
  const st = open ? (hover != null ? v.st.hover : v.st.open) : values.length ? v.st.value : v.st.closed
  const sn = open ? (hover != null ? 'hover' : 'open') : values.length ? 'value' : 'closed'
  const html = v.html[sn] || {}
  const item = (v.opts.open || v.opts.hover).inner[0]       // one captured <li> inside: checkbox + label
  const itemHtml = (o, checked) => item.replace(/(<p[^>]*>)[^<]*(<\/p>)/, `$1${o.replace(/</g, '&lt;')}$2`)
    .replace(/(<input class="border[^"]*")/, checked ? '$1 checked' : '$1')
  const liCls = (i) => (hover === i ? (v.opts.hover.cls.find((c) => /p-focus/.test(c)) || 'p-multiselect-item p-focus') : 'p-multiselect-item')
  const shown = options.filter((o) => !q || o.toLowerCase().includes(q.toLowerCase()))
  const toggleVal = (o) => onChange?.(values.includes(o) ? values.filter((x) => x !== o) : [...values, o])
  return (
    <div ref={ref} className={st.root} style={{ position: 'relative', ...(width ? { width } : {}) }} onMouseDown={(e) => { if (!forceOpen && !e.target.closest('.p-multiselect-panel')) setOpen((x) => !x) }}>
      <div className={v.st.closed.hidden} dangerouslySetInnerHTML={{ __html: v.html.closed.hidden || '' }} />
      <div className={st.labelContainer}>
        <div className={st.label}>
          {values.length ? values.map((o) => (
            <div key={o} className={v.st.value.token}>
              <span className={v.st.value.tokenLabel}>{o}</span>
              <span className={v.st.value.tokenIcon} onMouseDown={(e) => { e.stopPropagation(); toggleVal(o) }} />
            </div>
          )) : placeholder}
        </div>
      </div>
      {values.length > 0 && v.html.value.clearIcon && <span style={{ display: 'contents' }} onMouseDown={(e) => { e.stopPropagation(); onChange?.([]) }} dangerouslySetInnerHTML={{ __html: v.html.value.clearIcon }} />}
      <div className={st.trigger} dangerouslySetInnerHTML={{ __html: html.trigger || v.html.closed.trigger }} />
      {open && (
        // DIVERGES: PrimeReact appends the panel to <body> with a computed top/left; here it sits under the box (position from the box).
        <div className={v.st.open.panel} style={{ position: 'absolute', top: 'calc(100% + 4px)', left: 0, zIndex: 1000, minWidth: '100%' }}>
          <span style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: v.html.open.panelHidden || '' }} />
          <div className={v.st.open.header} onInput={(e) => setQ(e.target.value)} dangerouslySetInnerHTML={{ __html: v.html.open.header }} />
          <div className={v.st.open.itemsWrapper} style={css2obj(v.html.open.itemsWrapperStyle || 'max-height: 200px')}>
            <ul className={v.st.open.items} role="listbox" aria-multiselectable="true">
              {shown.map((o, i) => (
                <li key={o} className={liCls(i)} role="option" aria-selected={values.includes(o)} onMouseEnter={() => setHover(i)}
                  onMouseDown={(e) => { e.preventDefault(); toggleVal(o) }} dangerouslySetInnerHTML={{ __html: itemHtml(o, values.includes(o)) }} />
              ))}
            </ul>
          </div>
          <span style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: v.html.open.panelHidden || '' }} />
        </div>
      )}
    </div>
  )
}

export const LIVE_DROPDOWN_VARIANTS = Object.keys(DD)
